import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Boot failure triage","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/boot-failures.md","filePath":"troubleshooting/boot-failures.md"}'),s={name:"troubleshooting/boot-failures.md"};function i(l,e,n,h,c,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="boot-failure-triage" tabindex="-1">Boot failure triage <a class="header-anchor" href="#boot-failure-triage" aria-label="Permalink to &quot;Boot failure triage&quot;">​</a></h1><h2 id="the-boot-log-is-a-checklist" tabindex="-1">The boot log is a checklist <a class="header-anchor" href="#the-boot-log-is-a-checklist" aria-label="Permalink to &quot;The boot log is a checklist&quot;">​</a></h2><p>The kernel prints one line per subsystem IN BRING-UP ORDER (the order is <a href="./../arch/boot-flow.html">arch/boot-flow.md</a>). Diagnosis:</p><ol><li><strong>Nothing at all on serial</strong> - GRUB didn&#39;t run or the ISO entry is wrong. Boot the ISO&#39;s other slot entry; try BIOS vs UEFI.</li><li><strong>Stops before <code>long mode entry OK</code></strong> - boot.S stage: the multiboot2 handshake failed (bad magic/mbi) - capture with <code>-serial file:</code> and check the mbi tag parse.</li><li><strong>Stops at a driver line</strong> - that family&#39;s probe failed on your hardware; the message above it names the device. Remove the device (or the QEMU flag) to confirm.</li><li><strong>Reaches <code>boot complete</code> but no prompt</strong> - shell init; extremely rare (the 233-command registration line would be the tell).</li><li><strong>Reboots after the prompt</strong> - panic or watchdog: check /etc crashlog after the second boot (<code>dumpinfo</code>, <code>crashlog</code>), and the serial dump during the event.</li></ol><h2 id="the-self-tests-are-your-friends" tabindex="-1">The self-tests are your friends <a class="header-anchor" href="#the-self-tests-are-your-friends" aria-label="Permalink to &quot;The self-tests are your friends&quot;">​</a></h2><p>The boot sequence already proves: exception path (3/3), shell registration (233), crash recovery armed. If those lines printed, the machine underneath is sound - look at the specific feature, not the platform.</p><h2 id="second-boot-analysis" tabindex="-1">Second-boot analysis <a class="header-anchor" href="#second-boot-analysis" aria-label="Permalink to &quot;Second-boot analysis&quot;">​</a></h2><p>The A/B flag + crashlog survive reboots on /etc. After any unexpected reset: <code>dmesg</code> (current boot), <code>crashlog</code>/<code>dumpinfo</code> (previous boot), <code>abcfg</code> (what GRUB tried to boot).</p>',8)])])}const b=o(s,[["render",i]]);export{u as __pageData,b as default};
